(function(){'use strict';
 const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const familyLabels={ACCOUNTING_STOCK:'회계 잔액',ACCOUNTING_FLOW:'회계 기간 합계',PRICE:'가격',TRADING:'거래 규모',CAPITALIZATION:'시가총액',PRECOMPUTED_LIQUIDITY:'계산된 유동성 통계',PRECOMPUTED_PRICE_RISK:'계산된 가격 위험 통계',OTHER_UNKNOWN:'기타 · 미분류'};
 const fieldLabels={current_assets:'유동자산',current_liabilities:'유동부채',retained_earnings:'이익잉여금',total_equity:'자본총계',total_liabilities:'부채총계',noncurrent_assets:'비유동자산',capital_stock:'자본금',total_assets:'자산총계',noncurrent_liabilities:'비유동부채',revenue_ttm:'매출 TTM',operating_income_ttm:'영업이익 TTM',pretax_income_ttm:'세전이익 TTM',net_income_ttm:'순이익 TTM',adj_close:'조정 종가',adv20:'ADV20 거래 지표',trading_value:'거래대금',market_cap:'시가총액',amihud_illiquidity_1m:'월별 Amihud 통계',daily_volatility_252d:'252일 일수익 변동성',max_daily_return_1m:'월중 최대 일수익률',asset_id:'종목 식별자',ym:'연월',market:'시장 구분'};
 const roles={NUMERIC_OPERAND:'값 계산',PREDICATE_OPERAND:'반환 비교값',MASK:'조건·마스크',GROUP_KEY:'그룹 기준',SORT_KEY:'정렬 기준',CONTROL:'제어 정보',INDEX_ALIGNMENT:'인덱스 정렬',FRAME_CONTROL:'프레임 정렬'};
 const methods={rolling:'행 이동창',shift:'행 시차',mean:'평균',std:'표준편차',var:'분산',where:'조건 마스크',groupby:'그룹 묶기',sort_values:'행 정렬',transform:'그룹 변환',log:'로그',sqrt:'제곱근',pow:'거듭제곱',eq:'같음 비교',gt:'초과 비교',notna:'결측 여부',operator:'산술·논리 연산',min:'최솟값',max:'최댓값',clip:'범위 제한'};
 const stateLabel={BOUNDED_STATIC_ANALYSIS:'규칙 내 추출',PARTIAL:'부분 · 미해석 있음',UNKNOWN:'미해석'};
 const unknownLabel={CONTROL_FLOW_OR_DERIVED_COLUMN_WRITE:'반복·분기 또는 파생 열 쓰기: v1에서 추적하지 않음',UNRESOLVED_PERIOD:'기간 표현식을 해석하지 않음',TRANSFORM_BODY_NOT_TRACED:'그룹 변환 함수 본문은 추적하지 않음',KEYWORD_GROUP_OR_SORT_NOT_TRACED:'키워드 그룹·정렬 기준은 추적하지 않음',UNRESOLVED_MIN_PERIODS:'최소 관측 수 미해석',DYNAMIC_OR_MULTI_FIELD_SELECTOR:'동적·복수 필드 선택 미해석',UNRESOLVED_SELECTOR_BASE:'필드 선택 원천 미확인',UNRESOLVED_NAME:'변수 결합 미확인',UNSUPPORTED_CALL:'지원 밖 함수 호출',UNSUPPORTED_EXPRESSION:'지원 밖 표현식'};
 let store=null,query='',family='ALL',status='ALL',limit=12,lastHash=null;
 function readRoute(){if(lastHash===location.hash)return;lastHash=location.hash;const p=new URLSearchParams(location.hash.split('?')[1]||'');query=p.get('inputq')||'';family=familyLabels[p.get('inputfamily')]?p.get('inputfamily'):'ALL';status=stateLabel[p.get('inputstatus')]?p.get('inputstatus'):'ALL';limit=12;}
 function saveRoute(){const p=new URLSearchParams(location.hash.split('?')[1]||'');for(const [key,value] of [['inputq',query.trim()],['inputfamily',family==='ALL'?'':family],['inputstatus',status==='ALL'?'':status]]){if(value)p.set(key,value);else p.delete(key);}p.set('section','inputs');history.replaceState(null,'','#coverage?'+p);lastHash=location.hash;}
 async function validate(diagnostic,catalog){
  if(!diagnostic)return;
  if(diagnostic.schema_version!=='frozen-source-structure-v1'||diagnostic.scope!=='AUTHENTICATED_RELEASED_RECORDS_ONLY'||diagnostic.records.length!==catalog.records.length||diagnostic.performance_used!==false||diagnostic.independent_dimension_computed!==false)throw Error('Source structure scope mismatch');
  const byId=new Map(catalog.records.map(r=>[r.record_id,r]));if(new Set(diagnostic.records.map(r=>r.record_id)).size!==byId.size)throw Error('Duplicate structure identity');
  const sha=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),b=>b.toString(16).padStart(2,'0')).join('');
  const stable=v=>Array.isArray(v)?v.map(stable):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])])):v;
  await Promise.all(diagnostic.records.map(async row=>{const original=byId.get(row.record_id);if(!original||row.packet_sha256!==original.provenance.packet_sha256||row.definition_hash!==original.provenance.definition_hash||row.source_sha256!==await sha(original.definition.source)||row.params_sha256!==await sha(JSON.stringify(stable(original.definition.params)))||row.analysis.runtime_or_pit_verified!==false||row.analysis.calendar_continuity_verified!==false)throw Error('Source structure frozen binding mismatch');}));
 }
 function matches(){const q=query.toLocaleLowerCase().trim();return store.data.records.filter(row=>{const r=store.records.get(row.record_id),a=row.analysis;return (status==='ALL'||a.status===status)&&(family==='ALL'||a.inputs.some(i=>i.family===family&&['NUMERIC_OPERAND','PREDICATE_OPERAND'].includes(i.role)))&&(!q||[r.cycle,r.factor_name,store.context.title(r.factor_name),...a.inputs.map(i=>i.field),...a.operations.map(o=>o.kind)].join(' ').toLocaleLowerCase().includes(q));}).sort((a,b)=>store.records.get(b.record_id).cycle-store.records.get(a.record_id).cycle||a.record_id.localeCompare(b.record_id));}
 const statusBadge=a=>`<span class="badge ${a.status==='BOUNDED_STATIC_ANALYSIS'?'neutral':'amber'}">${h(stateLabel[a.status]||'미확인')}</span>`;
 const line=span=>`L${span.line}${span.end_line===span.line?'':'–'+span.end_line}`;
 const evidence=span=>`<details class="source-code-evidence"><summary>${h(line(span))} · 코드 근거</summary><pre>${h(span.text)}</pre></details>`;
 function detail(row){const r=store.records.get(row.record_id),a=row.analysis,grouped=new Map();for(const i of a.inputs){if(!grouped.has(i.field))grouped.set(i.field,[]);grouped.get(i.field).push(i);}
  const periodOps=a.operations.filter(o=>o.kind==='rolling'||o.kind==='shift');
  return `<div class="source-detail-grid"><section><h4>반환값에 연결된 필드 · 문법상 역할</h4>${[...grouped].map(([field,rows])=>`<div class="source-field"><strong>${h(fieldLabels[field]||field)}</strong><code>${h(field)}</code><div>${[...new Set(rows.map(i=>i.role))].map(role=>`<span class="source-role">${h(roles[role]||role)}</span>`).join('')}</div><details class="source-code-evidence"><summary>참조 ${rows.length}곳 · 원문 보기</summary>${rows.map(i=>`<small>${h(line(i.source_span))} · ${h(roles[i.role]||i.role)}</small><pre>${h(i.source_span.text)}</pre>`).join('')}</details></div>`).join('')||'<p>이 제한된 분석기로 입력 의존성을 확인하지 못했습니다. 입력이 없다는 뜻이 아닙니다.</p>'}</section><section><h4>기간과 계산 연산</h4>${periodOps.length?periodOps.map(o=>`<div class="source-period"><strong>${h(methods[o.kind])} ${o.period?.status!=='UNKNOWN'&&o.period?.value!=null?h(o.period.value):'미해석'}</strong><p>${o.kind==='rolling'?'달력 연속 기간을 보장하지 않는 행 이동창':'종목 내 행 순서에 따른 시차'}${o.keywords?.min_periods?' · 최소 관측 '+h(o.keywords.min_periods.status==='UNKNOWN'?'미해석':o.keywords.min_periods.value):''}</p>${o.period?.param?`<code>${h(o.period.expression)} → params.${h(o.period.param)}</code>`:''}${evidence(o.source_span)}</div>`).join(''):'<p>이 규칙에서 직접 추출한 행 창·시차가 없습니다. 선언된 기간이 없거나 정적 추적 밖일 수 있습니다.</p>'}<p class="chart-note">연월 필드를 조건에 사용: ${a.calendar_month_field_in_mask?'확인':'이 추출에서 미확인'} · 달력 연속성 검증: 하지 않음. 가중치 역할·상관/베타 수식 모티프는 자동 판정하지 않습니다.</p><details class="source-code-evidence"><summary>기록된 연산 ${a.operations.length}개 · 순서와 원문</summary>${a.operations.map(o=>`<p><b>${h(methods[o.kind]||o.kind)}</b> · ${h(roles[o.role]||o.role)}${o.operators?' · '+h(o.operators.join(', ')):''}</p>${evidence(o.source_span)}`).join('')}</details></section></div>${a.unknowns.length?`<div class="source-unknown"><h4>해석하지 않은 부분</h4>${a.unknowns.map(u=>`<p>${h(unknownLabel[u.code]||u.code)}</p>${u.source_span?evidence(u.source_span):''}`).join('')}</div>`:''}<p class="chart-note">시행 ${h(r.cycle)} · 원래 경제 영역 주석을 보충하거나 과거 정의를 수정하지 않습니다.</p>${store.context.recordButton(r,'원래 연구의 가설·근거 보기')}${store.context.source(r)}<code class="coverage-hash">source SHA-256 ${h(row.source_sha256)}<br>params SHA-256 ${h(row.params_sha256)}</code>`;
 }
 function rows(){const matched=matches();return `<p class="chart-note" aria-live="polite">${matched.length}개 시행 · ${Math.min(limit,matched.length)}개 표시 · 계산 템플릿의 ‘반복된 코드만’ 필터와 독립적으로 검색합니다.</p>${matched.slice(0,limit).map(row=>{const r=store.records.get(row.record_id),a=row.analysis,fields=[...new Set(a.inputs.filter(i=>['NUMERIC_OPERAND','PREDICATE_OPERAND'].includes(i.role)).map(i=>i.field))];return `<details class="source-case" data-source-record="${h(row.record_id)}"><summary><span class="source-cycle">${r.cycle}</span><span><strong>${h(store.context.title(r.factor_name))}</strong><small>${h(fields.map(f=>fieldLabels[f]||f).join(' · ')||'이 분석기에서 값 입력 미확인')}</small></span>${statusBadge(a)}</summary><div class="source-case-body"></div></details>`;}).join('')||'<p class="empty">이 필터에 맞는 시행이 없습니다. 이름·사이클 또는 입력 필드를 바꿔 검색할 수 있습니다.</p>'}${matched.length>limit?'<button class="small-button" data-source-more>12개 더 보기</button>':''}`;}
 function render(data,records,context){if(!data)return '<section class="panel"><h3>코드 입력 진단 미생성</h3><p>기존 frozen 정의는 보존돼 있으며 추가 분석은 아직 표시하지 않습니다.</p></section>';store={data,records:new Map(records.map(r=>[r.record_id,r])),context};readRoute();const count=data.records.length;
  return `<section class="source-structure" id="coverage-inputs"><div class="section-head"><div><span class="eyebrow">SOURCE REFERENCES / 실행 없이 읽은 코드</span><h2>코드가 참조하는 입력 · 계산구조</h2></div></div><div class="panel"><p>경제 영역의 미분류를 덮어쓰지 않고, 동결 코드의 반환값에 연결된 필드와 연산만 읽었습니다. <b>실제 관측·PIT·가용 데이터 검증이 아닙니다.</b> 이름·가설 문장·성과·OOS 결과로 분류하지 않습니다.</p><div class="source-family-grid">${Object.entries(familyLabels).filter(([key])=>data.numeric_family_record_counts[key]).map(([key,label])=>`<button data-source-family="${key}" class="source-family" aria-label="${h(label)}를 참조하는 시행 필터"><span>${h(label)}</span><strong>${data.numeric_family_record_counts[key]}<small> / ${count}</small></strong><span class="source-meter"><i style="width:${data.numeric_family_record_counts[key]/count*100}%"></i></span></button>`).join('')}</div><p class="chart-note">값 계산·반환 비교값의 필드 참조 수, 중복 포함. 그룹·정렬·조건 전용 입력은 이 숫자에서 제외합니다. 미해석 부분도 있어 전체 입력의 완전한 목록은 아닙니다. 가중치도 숫자 피연산자일 수 있으나 그 역할은 별도로 추론하지 않습니다.</p><div class="source-status-buttons"><button data-source-status="ALL" aria-pressed="${status==='ALL'}">전체 ${count}</button>${Object.entries(stateLabel).map(([key,label])=>`<button data-source-status="${key}" aria-pressed="${status===key}">${h(label)} ${data.counts[key]||0}</button>`).join('')}</div><p class="chart-note">‘규칙 내 추출’은 분석기의 지원 범위를 뜻합니다. 복잡한 수식의 의미·동등성이나 경제적 메커니즘을 검증한 등급이 아닙니다.</p><div class="toolbar wrap"><label class="search grow"><span>⌕</span><input id="source-search" type="search" value="${h(query)}" placeholder="cycle 230 · adj_close · rolling" aria-label="입력 계산구조 검색"></label><label class="source-family-select">값 입력 <select id="source-family"><option value="ALL">전체</option>${Object.entries(familyLabels).map(([key,label])=>`<option value="${key}" ${family===key?'selected':''}>${h(label)}</option>`).join('')}</select></label><button class="small-button" data-source-clear>필터 초기화</button></div><div id="source-results">${rows()}</div><details class="source section-gap"><summary>분석 규칙과 다음 준비 질문</summary><p>규칙 ${h(data.schema_version)} · literal 필드 선택, 순서가 보존된 alias 의존성, 제한된 연산과 정확히 일치하는 기간 상수만 추적합니다. 주석·사용되지 않는 변수는 원시 입력으로 세지 않습니다. 동적 선택·반복·미지원 함수는 미확인으로 남깁니다.</p><ol><li>기간만 다른 정의는 어떤 가설과 반증 관측을 구분하려 했는가?</li><li>회계 입력의 행 이동창은 새 공시 정보와 그대로 유지된 값을 얼마나 반복해서 읽는가?</li><li>매크로를 입력으로 쓰려면 당시 공개 시점이 보존된 자료 연결부터 준비됐는가?</li></ol><p>모두 정의 기반의 제안 질문이며 미실행입니다. 이 snippet에 매크로 필드가 보이지 않는다는 사실을 매크로 가설이 없다는 뜻으로 읽지 않습니다.</p></details></div></section>`;
 }
 function update(){const target=document.querySelector('#source-results');if(target)target.innerHTML=rows();const select=document.querySelector('#source-family');if(select)select.value=family;for(const b of document.querySelectorAll('[data-source-status]'))b.setAttribute('aria-pressed',String(b.dataset.sourceStatus===status));}
 document.addEventListener('toggle',e=>{const el=e.target;if(el?.matches?.('details[data-source-record]')&&el.open&&!el.querySelector('.source-case-body').children.length){const row=store?.data.records.find(r=>r.record_id===el.dataset.sourceRecord);if(row)el.querySelector('.source-case-body').innerHTML=detail(row);}},true);
 document.addEventListener('input',e=>{if(e.target.id==='source-search'){query=e.target.value;limit=12;saveRoute();update();}});
 document.addEventListener('change',e=>{if(e.target.id==='source-family'){family=e.target.value;limit=12;saveRoute();update();}});
 document.addEventListener('click',e=>{const f=e.target.closest('[data-source-family]'),s=e.target.closest('[data-source-status]');if(f)family=f.dataset.sourceFamily;if(s)status=s.dataset.sourceStatus;if(e.target.closest('[data-source-clear]')){query='';family='ALL';status='ALL';const input=document.querySelector('#source-search');if(input)input.value='';}else if(e.target.closest('[data-source-more]')){limit+=12;update();return;}else if(!f&&!s)return;limit=12;saveRoute();update();});
 window.SourceStructureUI=Object.freeze({render,validate});
})();

(function(){'use strict';
 const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let status=null,failure=false,pending=false,context=null,query='',onlyRepeated=true,limit=20,lastHash=null;
 function readRoute(){if(lastHash===location.hash)return;lastHash=location.hash;const params=new URLSearchParams(location.hash.split('?')[1]||'');query=params.get('q')||'';onlyRepeated=params.get('repeated')!=='0';limit=20;}
 function saveRoute(section){const params=new URLSearchParams(location.hash.split('?')[1]||'');if(query.trim())params.set('q',query);else params.delete('q');if(!onlyRepeated)params.set('repeated','0');else params.delete('repeated');if(section)params.set('section',section);const next='#coverage'+(params.size?'?'+params.toString():'');history.replaceState(null,'',next);lastHash=next;}
 function afterRender(){if(!status)return;const params=new URLSearchParams(location.hash.split('?')[1]||'');const section=params.get('section')||({'#coverage-domains':'domains','#coverage-templates':'templates'})[location.hash];if(['domains','templates','inputs'].includes(section))document.querySelector('#coverage-'+section)?.scrollIntoView({block:'start'});}
 const h=escape;
 function bind(s,catalog){
  if(s.schema_version!=='public-research-status-v1'||s.scope!=='AUTHENTICATED_RELEASED_RECORDS_ONLY'||s.counts.released!==catalog.records.length||s.records.length!==catalog.records.length)throw Error('Coverage scope mismatch');
  const records=new Map(catalog.records.map(r=>[r.record_id,r]));
  if(new Set(s.records.map(r=>r.record_id)).size!==records.size)throw Error('Coverage duplicate identity');
  for(const r of s.records){const original=records.get(r.record_id);if(!original||original.provenance.packet_sha256!==r.packet_sha256||original.provenance.definition_hash!==r.definition_hash)throw Error('Coverage identity mismatch');}
  return s;
 }
 function load(catalog,rerender){if(pending||status||failure)return;pending=true;fetch('./data/research-status.json').then(r=>{if(!r.ok)throw Error('Missing coverage');return r.json();}).then(async s=>{bind(s,catalog);await window.SourceStructureUI.validate(s.source_structure,catalog);status=s;pending=false;rerender();}).catch(()=>{failure=true;pending=false;rerender();});}
 const stat=(label,value,note)=>`<div class="coverage-stat"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`;
 const section=(k,t)=>`<div class="section-head"><div><span class="eyebrow">${k}</span><h2>${t}</h2></div></div>`;
 const recordButton=(r,text)=>`<button class="text-button" data-record="${h(r.record_id)}">${h(text||context.title(r.factor_name))} ↗</button>`;
 const source=(r)=>`<details class="source"><summary>동결 정의 · 출처 확인</summary><dl class="coverage-identity"><dt>공개 카탈로그 위치</dt><dd><a href="./data/research-catalog.json#${h(r.catalog_pointer)}">${h(r.catalog_pointer)}/definition ↗</a></dd><dt>definition_hash</dt><dd><code>${h(r.definition_hash)}</code></dd><dt>packet_sha256</dt><dd><code>${h(r.packet_sha256)}</code></dd></dl></details>`;
 function matches(includeSingletons=false){const q=query.toLocaleLowerCase().trim(),byId=new Map(status.records.map(r=>[r.record_id,r]));return status.templates.filter(t=>(!onlyRepeated||includeSingletons||t.record_ids.length>1)&&(!q||(!/^\d+$/.test(q)&&t.id.includes(q))||t.record_ids.some(id=>{const r=byId.get(id);if(/^\d+$/.test(q))return r.cycle===Number(q);return [r.cycle,r.factor_name,context.title(r.factor_name),JSON.stringify(r.params)].join(' ').toLocaleLowerCase().includes(q);})));}
 function templates(){const rows=matches(),byId=new Map(status.records.map(r=>[r.record_id,r]));return `<div class="table-caption" aria-live="polite"><strong>${rows.length}개 코드 템플릿</strong><span>표시 ${Math.min(limit,rows.length)}개 · 모든 시행 별도 보존</span></div>${rows.slice(0,limit).map(t=>{const members=t.record_ids.map(id=>byId.get(id)).sort((a,b)=>a.cycle-b.cycle);return `<details class="coverage-template"><summary><span class="coverage-template-count">${members.length}<small>시행</small></span><span><strong>${h(context.title(members[0].factor_name))}${members.length>1?' 외 '+(members.length-1)+'개':''}</strong><small>cycle ${members.map(r=>r.cycle).join(' · ')}</small></span><code>${t.id.slice(0,10)}</code></summary><p>동일한 보존 계산 코드입니다. 아래 파라미터·우대 방향·리밸런싱 차이를 별도로 읽습니다. 같은 경제 메커니즘이나 독립 재현으로 인증하지 않습니다.</p><div class="coverage-members">${members.map(r=>`<article><span class="eyebrow">CYCLE ${r.cycle}</span><h3>${recordButton(r)}</h3><code>${h(r.factor_name)}</code><dl><dt>파라미터</dt><dd><code>${h(JSON.stringify(r.params))}</code></dd><dt>원시 값 우대 방향</dt><dd>${r.predicted_sign===1?'높은 값':r.predicted_sign===-1?'낮은 값':'미수록'}</dd><dt>리밸런싱</dt><dd>${r.rebalance_months==null?'미수록':r.rebalance_months+'개월'}</dd><dt>추가 재무입력</dt><dd>${r.financial_inputs_state==='DECLARED'?r.inputs_declared+'개 선언':r.financial_inputs_state==='NO_ADDITIONAL_FINANCIAL_INPUTS'?'선언된 추가 재무입력 없음 · 공통 시장입력은 별도':'선언 미기록'}</dd></dl>${source(r)}</article>`).join('')}</div></details>`;}).join('')||`<div class="empty"><p>검색 조건에 맞는 템플릿이 없습니다.</p>${onlyRepeated&&query.trim()&&matches(true).length?`<p>‘반복된 코드만’ 필터에 가려진 ${matches(true).length}개 템플릿이 있습니다.</p><button class="small-button" data-coverage-include-singletons>단일 코드도 포함해서 보기</button>`:onlyRepeated?'<p>현재 반복된 코드만 보고 있습니다. 필터를 해제하면 단일 코드도 검색합니다.</p>':''}</div>`}${rows.length>limit?'<button class="small-button" data-coverage-more>20개 더 보기</button>':''}`;}
 function render(catalog,{title},rerender){readRoute();context={catalog,title};load(catalog,rerender);if(!status)return `<section class="panel"><h1>팩터 공간</h1><p>${failure?'인증 카탈로그와 결합된 진단을 불러오지 못했습니다. 분류나 다양성 값을 대신 만들지 않습니다.':'보존 정의와 진단 범위를 확인하고 있습니다.'}</p></section>`;
 const c=status.counts,d=status.diagnostics,g=status.regimes,identity=status.historical_gold_current_identity;
 const missing=d.find(x=>x.section==='execution_costs')?.status_counts.NOT_COLLECTED||0;
 const label={input_quality:'입력 품질',controlled_comparison:'통제 비교',economic_outcomes:'경제적 결과',execution_costs:'실행 비용',monthly_performance:'월별 성과',selection_profile:'선택 종목 특성'};
 return `<div class="coverage-page"><div class="page-heading"><div><div class="eyebrow">RESEARCH COVERAGE · READ ONLY</div><h1>많이 만들었는가,<br>다르게 물었는가.</h1><p class="lede">경제적 질문, 계산의 변형, 실제 점수의 차이를 나눠 봅니다.</p></div><a class="small-button" href="#map">연구 지도 ↗</a></div><div class="coverage-scope"><span class="badge blue">공개 인증 시행 ${c.released}건</span><p>이 화면의 분모는 공개된 cycle ${Math.min(...status.records.map(r=>r.cycle))}–${Math.max(...status.records.map(r=>r.cycle))}입니다. 보류 ${c.withheld}건은 내용에서 제외합니다. 현재 코드 정의 전체·과거 Gold 집합과 섞지 않습니다.</p></div><div class="coverage-three"><article class="panel coverage-axis"><span class="step">01 / ECONOMIC QUESTION</span><h2>무엇을 설명하려는가</h2>${stat('경제 영역 주석 미기록',c.unknown_domains+'/'+c.released,'미기록 ≠ 미탐색')}<p>가설과 반증 조건의 문장은 각각 ${c.mechanism_text}·${c.falsification_text}건 있습니다. 경제 영역과 실제 반증 관측을 검토한 분류는 별도입니다.</p><a class="text-button" href="#coverage?section=domains">분류의 경계 ↓</a></article><article class="panel coverage-axis"><span class="step">02 / FROZEN CALCULATION</span><h2>무엇을 다르게 계산했나</h2>${stat('정확히 같은 코드별 묶음',c.templates,'반복 '+c.repeated_template_groups+'묶음 · '+c.repeated_template_members+'시행')}<p>원래 계산 코드로만 묶습니다. 기간·방향·리밸런싱은 남기며, 묶어도 시행 수와 다중검정 수를 줄이지 않습니다.</p><a class="text-button" href="#coverage?section=templates">계산 변형 탐색 ↓</a><a class="text-button" href="#coverage?section=inputs">입력·계산구조 탐색 ↓</a></article><article class="panel coverage-axis"><span class="step">03 / EMPIRICAL DIFFERENCE</span><h2>실제로 다른 신호인가</h2>${stat('공통표본 상관 · 유효차원','미산출','NOT_COMPUTED')}<p>같은 적격 종목·월의 동결 정의 점수 행렬이 필요합니다. 코드 개수나 이름 개수로 독립적인 투자 기회 수를 계산하지 않습니다.</p><span class="badge amber">공통 점수 행렬 필요</span></article></div>
 ${section('ANNOTATION, NOT EMPTY SPACE','분류를 모른다는 것부터 기록합니다')}<section class="panel" id="coverage-domains"><p>연구 정책에 선언된 ${status.domains.length}개 탐색 영역입니다. 현재 공개 동결 기록의 영역 선언 ${c.declared_domains}건, 검토된 별도 주석 ${c.sidecar_domains}건입니다. 아래 영역의 주석 ${c.unknown_domains}건이 미기록이라는 뜻이며, 각 영역에 연구가 없다는 뜻이 아닙니다.</p><div class="coverage-domains">${status.domains.map(x=>`<div><strong>${h(x.label)}</strong><small>${x.count}건 분류 확인 · 나머지 미확인</small></div>`).join('')}</div><details class="source"><summary>주석 원칙 · 원본을 바꾸지 않는 분류</summary><p>record ID, definition hash, packet hash에 결합한 별도 주석만 수용합니다. 이름·현재 코드·성과·텍스트 유사도로 과거 경제 영역을 자동 보충하지 않습니다. 주석 리비전 ${h(status.annotation_revision)}. 현재 주석은 비어 있습니다.</p><p>계산 코드의 줄바꿈과 바깥 공백만 정규화해 SHA-256을 계산했습니다. 코드가 달라도 경제적으로 같은 신호일 수 있으므로 ${c.templates}개는 독립 수식·독립 메커니즘의 개수가 아닙니다.</p></details></section>
 ${window.SourceStructureUI.render(status.source_structure,status.records,{title:context.title,source,recordButton})}
 ${section('TEMPLATE EXPLORER','같은 계산에서 달라진 조건')}<section id="coverage-templates"><div class="toolbar wrap"><label class="search grow"><span>⌕</span><input id="coverage-search" type="search" value="${h(query)}" placeholder="팩터 이름 · cycle · 파라미터" aria-label="계산 템플릿 검색"></label><label class="coverage-checkbox"><input id="coverage-repeated" type="checkbox" ${onlyRepeated?'checked':''}> 반복된 코드만</label></div><div id="coverage-results">${templates()}</div></section>
 ${section('EVIDENCE COVERAGE','검토한 수와 측정한 수는 다릅니다')}<div class="two-grid"><section class="panel"><h3>교훈 ${c.reviewed}건 검토 · 실행 비용 ${missing}건 미수집</h3><p>이 표는 원래 packet의 상세 진단 섹션 상태입니다. gate의 비용 가정이나 다른 요약 숫자가 있다는 이유로 실행 진단을 수집했다고 바꾸지 않습니다.</p><div class="table-wrap"><table><thead><tr><th>진단</th><th>수집</th><th>부분</th><th>미수집</th></tr></thead><tbody>${d.map(x=>`<tr><td>${label[x.section]||h(x.section)}</td><td>${x.status_counts.AVAILABLE||0}</td><td>${x.status_counts.PARTIAL||0}</td><td>${x.status_counts.NOT_COLLECTED||0}</td></tr>`).join('')}</tbody></table></div><p class="chart-note">추가 재무입력 선언 ${c.input_list_present}/${c.released}건 · 추가 재무입력 없음 ${c.financial_inputs_empty}건 · 선언 미기록 ${c.financial_inputs_unrecorded}건. 공통 시장입력은 별도입니다. 원시 입력 프로필 ${c.raw_input_profile_collected}/${c.released}건. 과거 packet의 누락은 당시 미수집 상태로 보존합니다.</p></section><section class="panel"><h3>레짐 진단 ${g.length}건 · 표본 재사용을 구분</h3>${g.map(r=>`<p>${recordButton(status.records.find(x=>x.record_id===r.record_id))}<br>${h(r.phase)} ${r.months}신호월 · UNKNOWN ${r.coarse.unknown}개월<br>세부 ${r.detail_cells}상태 중 ${r.detail_display_supported}상태가 설명 표시 조건을 충족합니다.</p>`).join('')||'<p>공개된 레짐 진단이 없습니다.</p>'}<p>12개월·3발생 구간은 표시 정책입니다. 모든 환경에서 고르게 검증됐다는 뜻이 아닙니다.</p><p>공개 캠페인 ${c.released_campaigns}개 중 ${c.reused_campaigns}개가 과거 구간 재사용입니다. 이 중 ${c.revealed_campaigns}개에서 ${c.confirmation_evaluated}개 후보의 confirmation 평가가 공개됐습니다. 반복 노출을 독립 확인 횟수로 세지 않습니다.</p><a class="text-button" href="#regimes">레짐 근거와 최신성 확인 ↗</a></section></div>
 ${section('NEXT MEASUREMENT','다음 단계는 새 팩터보다 연결의 검증')}<div class="three-grid"><article class="panel"><span class="step">01</span><h3>경제적 질문을 검토</h3><p>가설 원문과 반증 조건을 근거로 별도 주석을 검토합니다. 반증 관측을 실제로 수집했는지 따로 기록합니다.</p></article><article class="panel"><span class="step">02</span><h3>같은 표본을 확보</h3><p>적격 종목 → 입력 관측 → 연속 기간 → 유효 분모 → 유한 점수의 손실을 측정해야 합니다. 미래 수익 라벨의 가용성은 별도입니다.</p><span class="badge neutral">아직 공통 퍼널 미산출</span></article><article class="panel"><span class="step">03</span><h3>점수의 중복을 측정</h3><p>공통표본 상관 행렬이 마련되면 신호의 중복과 유효차원을 볼 수 있습니다. 쌍별 상관 중앙값 표를 고유값 분석에 대신 넣지 않습니다.</p><span class="badge neutral">아직 행렬 미산출</span></article></div>
 <details class="panel source section-gap"><summary>범위 · 분모 · 원문 및 연구 방법의 출처</summary><p>이 진단 ${c.released}건과 현재 승인 비교 ${identity.current_definitions??'미확인'}개는 다른 집합입니다. 비교 대상의 과거 정의는 ${identity.changed??'미확인'}개 변경, ${identity.unknown??'미확인'}개 미확인 상태로 유지하며 연결 실패를 삭제하지 않습니다. 현재 코드 이름이 같다는 이유로 과거 시행의 정의로 대체하지 않습니다.</p><p>원천 스냅샷 ${h(status.source_snapshot_as_of)} · 표시 점검일 ${h(status.display_audit_as_of)}. 점검일 갱신은 새 자료 수집이나 새 연구 성과가 아닙니다.</p><p><a href="https://onlinelibrary.wiley.com/doi/10.1111/jofi.13249" target="_blank" rel="noopener">Jensen·Kelly·Pedersen (2023) ↗</a>는 미국 팩터의 CAPM 잔차 수익 상관으로 군집을 구성했습니다. 그 논문의 13개 주제를 이 한국 자료의 13개 독립 차원으로 옮기지 않습니다.</p><p><a href="https://arxiv.org/abs/1506.02629" target="_blank" rel="noopener">Dwork 외 (2015), 적응적 분석과 holdout 재사용 ↗</a>: 반복해서 결과를 보고 다음 질문을 바꾸는 과정은 고정된 한 번의 검증과 다릅니다. 이 화면의 그룹화는 이를 새로 통제하는 절차가 아닙니다.</p><p>이 자료는 연구 해석용입니다. 기존 승인된 정성 교훈 활용은 유지하며 원시 OOS 수치·성과 순위를 후보 생성에 새로 공급하지 않습니다.</p><a class="small-button" href="./data/research-status.json" download>진단 스냅샷 JSON ↓</a><code class="coverage-hash">catalog SHA-256 ${h(status.catalog_sha256)}</code></details></div>`;
 }
 function update(){const el=document.querySelector('#coverage-results');if(el)el.innerHTML=templates();}
 document.addEventListener('input',e=>{if(e.target.id==='coverage-search'){query=e.target.value;limit=20;saveRoute();update();}});
 document.addEventListener('change',e=>{if(e.target.id==='coverage-repeated'){onlyRepeated=e.target.checked;limit=20;saveRoute();update();}});
 document.addEventListener('click',e=>{if(e.target.closest('[data-coverage-more]')){limit+=20;update();}if(e.target.closest('[data-coverage-include-singletons]')){onlyRepeated=false;limit=20;const checkbox=document.querySelector('#coverage-repeated');if(checkbox)checkbox.checked=false;saveRoute();update();document.querySelector('#coverage-search')?.focus();}const anchor=e.target.closest('a[href^="#coverage?section="]');if(anchor){e.preventDefault();saveRoute(new URLSearchParams(anchor.hash.split('?')[1]).get('section'));afterRender();}});
 window.ResearchStatusUI=Object.freeze({render,bind,afterRender});
})();
